CREATE TABLE parties (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), party_type TEXT NOT NULL, legal_name TEXT NOT NULL, display_name TEXT NOT NULL, country_code TEXT NOT NULL, status TEXT NOT NULL, verification_status TEXT NOT NULL, risk_tier TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX parties_workspace_status_idx ON parties(workspace_id,status);
CREATE TABLE verification_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), party_id UUID NOT NULL REFERENCES parties(id), verification_type TEXT NOT NULL, provider_code TEXT NOT NULL, provider_request_reference TEXT NOT NULL, status TEXT NOT NULL, requested_by UUID NOT NULL, requested_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE verification_results (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), verification_request_id UUID NOT NULL REFERENCES verification_requests(id), party_id UUID NOT NULL REFERENCES parties(id), verification_type TEXT NOT NULL, result TEXT NOT NULL, risk_flags JSONB NOT NULL DEFAULT '[]', matched_attributes JSONB NOT NULL DEFAULT '[]', source_references JSONB NOT NULL DEFAULT '[]', provider_response_reference TEXT NOT NULL, verified_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ, review_status TEXT NOT NULL, reviewed_by UUID, reviewed_at TIMESTAMPTZ, supersedes_result_id UUID REFERENCES verification_results(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE beneficiary_account_references (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), party_id UUID NOT NULL REFERENCES parties(id), provider_id TEXT, account_reference_token TEXT NOT NULL, masked_account_identifier TEXT NOT NULL, institution_name TEXT NOT NULL, currency TEXT NOT NULL, country_code TEXT NOT NULL, verification_status TEXT NOT NULL, verified_name TEXT, verified_at TIMESTAMPTZ, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version INTEGER NOT NULL DEFAULT 1);
